9	import { useDoorHeight, useIsFrontSide, useSceneLightingMode } from '../store';
10	import { Connectors } from './Connectors';
11	import { Cylinder } from './Cylinder';
12	import { DoorApplication } from './DoorApplication';
13	import { InnerHandle } from './InnerHandle';
14	import { OuterHandle } from './OuterHandle';
15	import { HardwareGroup, ParametricDoor, ParametricHouse } from './parametric';
16	import {
17	  WALL_CENTER_Z,
18	  WALL_HEIGHT,
19	  WALL_THICKNESS,
20	} from './parametric/ParametricWall';
21	
22	interface Props {
23	  proposal?: Proposal;
24	  onLoadingChange?: (loading: boolean) => void;
25	}
26	
27	const SuspenseNotifier: FC<{
28	  onLoadingChange?: (loading: boolean) => void;
29	}> = ({ onLoadingChange }) => {
30	  useEffect(() => {
31	    onLoadingChange?.(false);
32	    return () => {
33	      onLoadingChange?.(true);
