45	interface DoorCameraControllerProps {
46	  controlsRef: React.RefObject<OrbitControlsImpl | null>;
47	  doorFocusY: number;
48	  isFront: boolean;
49	}
50	
51	const DoorCameraController: FC<DoorCameraControllerProps> = ({
52	  controlsRef,
53	  doorFocusY,
54	  isFront,
55	}) => {
56	  const { camera, invalidate } = useThree();
57	
58	  useEffect(() => {
59	    const controls = controlsRef.current;
60	
61	    if (!controls) return;
62	
63	    const interiorTargetZ = WALL_CENTER_Z - WALL_THICKNESS / 2 - 0.02;
64	    const target = new THREE.Vector3(
65	      0,
66	      doorFocusY,
67	      isFront ? 0 : interiorTargetZ,
68	    );
69	    const offset = isFront
70	      ? new THREE.Vector3(0, 0.8, 4.5)
71	      : new THREE.Vector3(0, 0.8, -4.5);
72	
73	    controls.target.copy(target);
74	    camera.position.copy(target).add(offset);
75	    camera.lookAt(target);
76	    controls.update();
77	    invalidate();
78	  }, [camera, controlsRef, doorFocusY, invalidate, isFront]);
79	
80	  return null;
81	};
82	
83	const ExposureController: FC<{ exposure: number }> = ({ exposure }) => {
84	  const { gl, invalidate } = useThree();
85	  useEffect(() => {
86	    gl.toneMappingExposure = exposure;
87	    invalidate();
88	  }, [gl, exposure, invalidate]);
89	  return null;
90	};
91	
92	const InteriorNightLamp: FC<{
93	  isNightMode: boolean;
94	  pointIntensity?: number;
95	  spotIntensity?: number;
96	}> = ({ isNightMode, pointIntensity = 11, spotIntensity = 13 }) => {
97	  const target = useMemo(() => {
98	    const nextTarget = new THREE.Object3D();
99	    nextTarget.position.set(0, -1.9, 0);
100	    return nextTarget;
101	  }, []);
102	
103	  return (
104	    <group position={interiorLampPosition}>
105	      <primitive object={target} />
106	      <mesh position={[0, 0.11, 0]}>
107	        <cylinderGeometry args={[0.045, 0.045, 0.22, 24]} />
108	        <meshStandardMaterial
109	          color="#2c3137"
110	          roughness={0.72}
111	          metalness={0.18}
112	        />
113	      </mesh>
114	      <mesh castShadow position={[0, -0.03, 0]}>
115	        <cylinderGeometry args={[0.22, 0.28, 0.18, 32]} />
116	        <meshStandardMaterial
117	          color="#d8c7a2"
118	          metalness={0.08}
119	          roughness={0.55}
120	        />
121	      </mesh>
122	      <mesh position={[0, -0.09, 0]}>
123	        <sphereGeometry args={[0.11, 24, 24]} />
124	        <meshStandardMaterial
125	          color="#ffe5b7"
126	          emissive="#ffcc7a"
127	          emissiveIntensity={isNightMode ? 2.9 : 0.12}
128	          roughness={0.2}
129	        />
130	      </mesh>
131	      <pointLight
132	        position={[0, -0.16, 0]}
133	        intensity={isNightMode ? pointIntensity : 0}
134	        distance={9}
135	        decay={1.4}
136	        color="#ffd8a6"
137	      />
138	      <spotLight
139	        position={[0, -0.07, 0]}
140	        target={target}
141	        angle={1.05}
142	        penumbra={1}
143	        decay={1.15}
144	        distance={11}
145	        intensity={isNightMode ? spotIntensity : 0}
146	        color="#ffd8a6"
147	        castShadow
148	        shadow-bias={-0.0001}
149	        shadow-radius={5}
150	        shadow-mapSize-width={2048}
151	        shadow-mapSize-height={2048}
152	      />
153	    </group>
154	  );
155	};
156	
157	const WallMountedLights: FC<{
158	  isNightMode: boolean;
159	  isVisible: boolean;
160	  nightIntensity?: number;
161	}> = ({ isNightMode, isVisible, nightIntensity = 18 }) => {
162	  const targets = useMemo(
163	    () =>
164	      wallLightPositions.map((_, index) => {
165	        const target = new THREE.Object3D();
166	        target.position.set(index === 0 ? 0.92 : -0.92, -1.15, -1.05);
167	        return target;
168	      }),
169	    [],
170	  );
171	
172	  return (
173	    <group>
174	      {wallLightPositions.map((position, index) => (
175	        <group key={`wall-light-${index}`} position={position}>
176	          <primitive object={targets[index]} />
177	          <mesh castShadow position={[0, 0, -0.025]}>
178	            <boxGeometry args={[0.16, 0.22, 0.05]} />
179	            <meshStandardMaterial
180	              color="#2c3137"
181	              roughness={0.82}
182	              metalness={0.18}
183	            />
184	          </mesh>
185	          <mesh position={[0, -0.02, 0.005]}>
186	            <boxGeometry args={[0.09, 0.11, 0.03]} />
187	            <meshStandardMaterial
188	              color="#ffe1b3"
189	              emissive="#ffc76d"
190	              emissiveIntensity={isNightMode ? 2.3 : 0.06}
191	              roughness={0.3}
192	            />
193	          </mesh>
194	          <spotLight
195	            position={[0, -0.02, 0.03]}
196	            target={targets[index]}
197	            angle={1.08}
198	            penumbra={1}
199	            decay={1}
200	            distance={13}
201	            intensity={isNightMode && isVisible ? nightIntensity : 0}
202	            color="#ffe0b0"
203	            castShadow
204	            shadow-bias={-0.0001}
205	            shadow-radius={3}
206	            shadow-mapSize-width={2048}
207	            shadow-mapSize-height={2048}
208	          />
209	        </group>
210	      ))}
211	    </group>
