215	export const Door: FC<Props> = ({ proposal, onLoadingChange }) => {
216	  const isFront = useIsFrontSide();
217	  const selectedDoorHeightMm = useDoorHeight();
218	  const selectedLightingMode = useSceneLightingMode();
219	  const controlsRef = useRef<OrbitControlsImpl | null>(null);
220	  const isNightMode = selectedLightingMode?.id === 'night';
221	  const minDistance = isFront ? 3 : 3.2;
222	  const maxDistance = isFront ? 8 : 6.5;
223	  const minPolarAngle = isFront ? Math.PI / 3 : 1.22;
224	  const maxPolarAngle = isFront ? Math.PI / 2 : 1.5;
225	  const maxAzimuthAngle = useMemo(
226	    () => (isFront ? Math.PI / 6 : Math.PI + Math.PI / 6),
227	    [isFront],
228	  );
229	  const minAzimuthAngle = useMemo(() => {
230	    return isFront ? -Math.PI / 6 : Math.PI - Math.PI / 6;
231	  }, [isFront]);
232	  const doorFocusY = useMemo(() => {
233	    const doorHeight =
234	      clampDoorHeightMm(proposal?.doorHeight ?? selectedDoorHeightMm) / 1000;
235	
236	    return -WALL_HEIGHT / 2 + 0.03 + doorHeight / 2;
237	  }, [proposal?.doorHeight, selectedDoorHeightMm]);
238	
239	  const {
240	    exposure,
241	    dayKeyX,
242	    dayKeyY,
243	    dayKeyZ,
244	    dayKeyIntensity,
245	    dayDetailX,
246	    dayDetailY,
247	    dayDetailZ,
248	    dayDetailIntensity,
249	    dayAmbIntensity,
250	    dayHemiIntensity,
251	    nightDirIntensity,
252	    nightAmbIntensity,
253	    nightHemiIntensity,
254	    nightWallLampIntensity,
255	    nightPointLampIntensity,
256	    nightSpotLampIntensity,
257	  } = useControls({
258	    'Post FX': folder({
259	      exposure: { value: 1.0, min: 0.1, max: 3, step: 0.05, label: 'Exposure' },
260	    }),
261	    'Day Lights': folder(
262	      {
263	        'Key Light (raking)': folder({
264	          dayKeyX: { value: -8, min: -8, max: 10, step: 0.1, label: 'X' },
265	          dayKeyY: { value: 10, min: 0, max: 10, step: 0.1, label: 'Y' },
266	          dayKeyZ: { value: 1.5, min: -2, max: 12, step: 0.1, label: 'Z' },
267	          dayKeyIntensity: {
268	            value: 6,
269	            min: 0,
270	            max: 6,
271	            step: 0.05,
272	            label: 'Intensity',
273	          },
274	        }),
275	        'Detail Fill (opposite side)': folder({
276	          dayDetailX: { value: 4.6, min: -8, max: 8, step: 0.1, label: 'X' },
277	          dayDetailY: { value: 3.0, min: 0, max: 8, step: 0.1, label: 'Y' },
278	          dayDetailZ: { value: -5.3, min: -8, max: 10, step: 0.1, label: 'Z' },
279	          dayDetailIntensity: {
280	            value: 0.7,
281	            min: 0,
282	            max: 3,
283	            step: 0.05,
284	            label: 'Intensity',
285	          },
286	        }),
287	        dayAmbIntensity: {
288	          value: 0.2,
289	          min: 0,
290	          max: 3,
291	          step: 0.05,
292	          label: 'Ambient',
293	        },
294	        dayHemiIntensity: {
295	          value: 0.25,
296	          min: 0,
297	          max: 3,
298	          step: 0.05,
299	          label: 'Hemisphere',
300	        },
301	      },
302	      { collapsed: false },
303	    ),
304	    'Night Lights': folder(
305	      {
306	        nightDirIntensity: {
307	          value: 5,
308	          min: 0,
309	          max: 5,
310	          step: 0.05,
311	          label: 'Directional',
312	        },
313	        nightAmbIntensity: {
314	          value: 0.24,
315	          min: 0,
316	          max: 2,
317	          step: 0.05,
318	          label: 'Ambient',
319	        },
320	        nightHemiIntensity: {
321	          value: 0,
322	          min: 0,
323	          max: 2,
324	          step: 0.05,
325	          label: 'Hemisphere',
326	        },
327	        nightWallLampIntensity: {
328	          value: 9,
329	          min: 0,
330	          max: 60,
331	          step: 0.5,
332	          label: 'Wall Lamps',
333	        },
334	        nightPointLampIntensity: {
335	          value: 11,
336	          min: 0,
337	          max: 30,
338	          step: 0.5,
339	          label: 'Interior Pt',
340	        },
341	        nightSpotLampIntensity: {
342	          value: 13,
343	          min: 0,
344	          max: 40,
345	          step: 0.5,
346	          label: 'Interior Sp',
347	        },
348	      },
349	      { collapsed: true },
350	    ),
351	  });
352	
353	  return (
354	    <group position={[0, 0, 0]}>
355	      <ExposureController exposure={exposure} />
356	      <DoorCameraController
357	        controlsRef={controlsRef}
358	        doorFocusY={doorFocusY}
359	        isFront={isFront}
360	      />
361	      <OrbitControls
362	        ref={controlsRef}
363	        minDistance={minDistance}
364	        maxDistance={maxDistance}
365	        maxPolarAngle={maxPolarAngle}
366	        minPolarAngle={minPolarAngle}
367	        maxAzimuthAngle={maxAzimuthAngle}
368	        minAzimuthAngle={minAzimuthAngle}
369	        target={[0, doorFocusY, 0]}
370	        enablePan={false}
371	      />
372	      <SoftShadows size={25} samples={17} focus={0} />
373	      <color attach="background" args={[isNightMode ? '#0d1320' : '#edf1f4']} />
374	      <fog
375	        attach="fog"
376	        args={[
377	          isNightMode ? '#0d1320' : '#edf1f4',
378	          isNightMode ? 8 : 180,
379	          isNightMode ? 24 : 240,
380	        ]}
381	      />
382	      {isFront ? (
383	        <>
384	          {/* Key light — raking from the side to reveal engraved details */}
385	          <directionalLight
386	            {...lights.front}
387	            position={[dayKeyX, dayKeyY, dayKeyZ] as [number, number, number]}
388	            castShadow
389	            intensity={isNightMode ? nightDirIntensity : dayKeyIntensity}
390	            color={isNightMode ? '#a9bce0' : '#ffffff'}
391	            shadow-bias={-0.0001}
392	            shadow-radius={3}
393	            shadow-mapSize-width={4096}
394	            shadow-mapSize-height={4096}
395	            shadow-camera-left={-3}
396	            shadow-camera-right={3}
397	            shadow-camera-top={4}
398	            shadow-camera-bottom={-2}
399	            shadow-camera-near={0.5}
400	            shadow-camera-far={25}
401	          />
402	          {/* Detail fill — from the opposite side, softer, prevents full black shadows */}
403	          {!isNightMode && (
404	            <directionalLight
405	              position={
406	                [dayDetailX, dayDetailY, dayDetailZ] as [number, number, number]
407	              }
408	              intensity={dayDetailIntensity}
409	              color="#e8eeff"
410	            />
411	          )}
412	          <ambientLight
413	            intensity={isNightMode ? nightAmbIntensity : dayAmbIntensity}
414	            color={isNightMode ? '#8d9ab0' : '#ffffff'}
415	          />
416	          <hemisphereLight
417	            color={isNightMode ? '#94a7c6' : '#ffffff'}
418	            groundColor={isNightMode ? '#1b2028' : '#888888'}
419	            intensity={isNightMode ? nightHemiIntensity : dayHemiIntensity}
420	          />
421	          <directionalLight
422	            position={[2, 2, -3]}
423	            intensity={isNightMode ? 0.22 : 0.35}
424	            color={isNightMode ? '#b0c1dd' : '#ffffff'}
425	          />
426	          <pointLight
427	            position={[-2, 2, -2]}
428	            intensity={isNightMode ? 0 : 0.3}
429	            distance={7}
430	          />
431	          <pointLight
432	            position={[2, 2, -2]}
433	            intensity={isNightMode ? 0 : 0.3}
434	            distance={7}
435	          />
436	        </>
437	      ) : (
438	        <>
439	          <ambientLight
440	            intensity={isNightMode ? nightAmbIntensity * 0.75 : 0.35}
441	            color={isNightMode ? '#7d8ca3' : '#ffffff'}
442	          />
443	          <hemisphereLight
444	            color={isNightMode ? '#7183a0' : '#ffffff'}
445	            groundColor={isNightMode ? '#16181f' : '#888888'}
446	            intensity={isNightMode ? nightHemiIntensity * 0.52 : 0.2}
447	          />
448	        </>
449	      )}
450	      <WallMountedLights
451	        isNightMode={isNightMode}
452	        isVisible={isFront}
453	        nightIntensity={nightWallLampIntensity}
454	      />
455	      <InteriorNightLamp
456	        isNightMode={isNightMode || !isFront}
457	        pointIntensity={nightPointLampIntensity}
458	        spotIntensity={nightSpotLampIntensity}
459	      />
460	
461	      {/* House structure with the first-floor slab/ceiling restored */}
462	      <ParametricHouse proposal={proposal} />
463	
464	      {/* Door model + hardware — wrapped in Suspense so the scene stays
465	          rendered while new GLTFs load (only the models unmount, not the
466	          lights/camera/walls). */}
467	      <Suspense fallback={null}>
468	        <SuspenseNotifier onLoadingChange={onLoadingChange} />
469	        <ParametricDoor showWall={false} />
470	        <HardwareGroup>
471	          <DoorApplication proposal={proposal} />
472	          <Cylinder proposal={proposal} />
473	          <Connectors proposal={proposal} />
474	          <OuterHandle proposal={proposal} />
475	          <InnerHandle proposal={proposal} />
476	        </HardwareGroup>
477	      </Suspense>
478	    </group>
479	  );
480	};
