6	import { useGLTF } from '@react-three/drei';
7	import { FC, useMemo } from 'react';
8	import * as THREE from 'three';
9	import { GLTF } from 'three-stdlib';
10	import { useDoorDesign } from '../store';
11	
12	type GLTFResult = GLTF & {
13	  nodes: {
14	    ['EL-34intarzijain001']: THREE.Mesh;
15	    ['EL-34intarzijaout001']: THREE.Mesh;
16	  };
17	  materials: {
18	    inoxcesljani: THREE.MeshStandardMaterial;
19	  };
20	};
21	
22	interface Props {
23	  proposal?: Proposal;
24	}
25	
26	export const DoorApplication: FC<Props> = ({ proposal }) => {
27	  const model = useDoorDesign();
28	  const modelSrc = useMemo(
29	    () => proposal?.design?.modelSrc || model.modelSrc,
30	    [proposal, model],
31	  );
32	  const { nodes, materials } = useGLTF(
