1	'use client';
2	
3	import { useTexture } from '@react-three/drei';
4	import { useThree } from '@react-three/fiber';
5	import { useEffect, useMemo, useRef } from 'react';
6	import * as THREE from 'three';
7	import {
8	  clampDoorHeightMm,
9	  clampDoorWidthMm,
10	} from '../../const';
11	import {
12	  useDoorHeight,
13	  useDoorLayout,
14	  useDoorLeftGlassWidth,
15	  useDoorRightGlassWidth,
16	  useSceneExteriorWallColor,
17	  useSceneExteriorWallFinish,
18	  useSceneInteriorWallColor,
19	  useDoorUpperGlassHeight,
20	  useDoorWidth,
21	} from '../../store';
22	import { sceneWallFinishes } from '../../const';
23	import { useFacadeTextures } from '../../hooks/useFacadeTextures';
24	import { useWallSurfaceMaterial } from '../../hooks/useWallSurfaceMaterial';
25	import {
26	  ParametricWall,
27	  WALL_CENTER_Z,
28	  WALL_HEIGHT,
29	  WALL_THICKNESS,
30	  WALL_WIDTH,
31	  WallHole,
32	  WallMaterialProps,
33	} from './ParametricWall';
34	import {
35	  ParametricWindow,
36	  WINDOW_HEIGHT,
37	  WINDOW_SILL_HEIGHT,
38	  WINDOW_WIDTH,
39	} from './ParametricWindow';
40	
41	// Door frame constants (must match ParametricDoor)
42	const FRAME_PROFILE_WIDTH = 0.066;
43	const FRAME_PROFILE_WIDTH_BOTTOM = 0.03;
44	
45	// House constants
46	const HOUSE_DEPTH = 10.0; // meters
47	const ROOF_THICKNESS = 0.15;
48	const ROOF_COLOR = '#555555';
49	const WALL_COLOR = '#e8e0d4';
50	const FOUNDATION_HEIGHT = 0.36;
51	const FOUNDATION_TOP_CLEARANCE = 0.005;
52	const INTER_FLOOR_SLAB_THICKNESS = 0.16;
53	const INTER_FLOOR_SLAB_INSET = 0.08;
54	const INTERIOR_FLOOR_SURFACE_OFFSET = 0.01;
55	const STEP_COUNT = 2;
56	const STEP_DEPTH = 1.0;
57	const FOUNDATION_COLOR = '#8e877f';
58	const DARK_CONCRETE_COLOR = '#6f6a64';
59	const STAIR_CONCRETE_COLOR = '#e6ddd0';
60	const LOWER_STEP_WIDTH = 5.2;
61	const UPPER_STEP_WIDTH = 6.4;
62	const UPPER_STEP_DEPTH = 1.44;
63	
64	// Fascia
65	const FASCIA_HEIGHT = 0.04;
66	const FASCIA_DEPTH = 0.02;
67	const FASCIA_COLOR = '#333333';
68	
69	// Window placement
70	const WINDOW_CENTER_X = -3.0; // left of door, good spacing on wider wall
71	const UPPER_WINDOW_CENTER_X = 3.0;
72	
73	// Convert mm to meters
74	const mmToM = (mm: number) => mm / 1000;
75	const FLOOR_Y = -WALL_HEIGHT / 2;
76	const CEILING_Y = WALL_HEIGHT / 2;
77	const FRONT_WALL_BACK_FACE_Z = WALL_CENTER_Z - WALL_THICKNESS / 2;
78	
79	/**
80	 * Helper: copies uv → uv2 so aoMap works on box geometries.
81	 */
82	function useUv2(ref: React.RefObject<THREE.Mesh | null>) {
83	  useEffect(() => {
84	    const mesh = ref.current;
85	    if (!mesh) return;
86	    const geom = mesh.geometry as THREE.BufferGeometry;
87	    const uv = geom.attributes.uv;
88	    if (uv && !geom.attributes.uv2) {
89	      geom.setAttribute('uv2', uv.clone());
90	    }
91	  }, [ref]);
92	}
93	
94	function useInteriorFloorMaterial(): WallMaterialProps {
95	  const { gl } = useThree();
96	  const sourceTextures = useTexture({
97	    map: '/textures/floor/Zebrano_Rift_Sawn_Natural_Finish_Veneer_Wood_basecolor_2K.png',
98	    normalMap:
99	      '/textures/floor/Zebrano_Rift_Sawn_Natural_Finish_Veneer_Wood_normal_2K.png',
100	    roughnessMap:
101	      '/textures/floor/Zebrano_Rift_Sawn_Natural_Finish_Veneer_Wood_roughness_2K.png',
102	  });
103	
104	  const textures = useMemo(() => {
105	    const anisotropy = Math.min(16, gl.capabilities.getMaxAnisotropy());
106	    const map = sourceTextures.map.clone();
107	    const normalMap = sourceTextures.normalMap.clone();
108	    const roughnessMap = sourceTextures.roughnessMap.clone();
109	
110	    [map, normalMap, roughnessMap].forEach((texture, index) => {
111	      texture.wrapS = THREE.RepeatWrapping;
112	      texture.wrapT = THREE.RepeatWrapping;
113	      texture.repeat.set(2.8, 5.6);
114	      texture.magFilter = THREE.LinearFilter;
115	      texture.minFilter = THREE.LinearMipmapLinearFilter;
116	      texture.anisotropy = anisotropy;
117	      texture.needsUpdate = true;
118	
119	      if (index === 0) {
120	        texture.colorSpace = THREE.SRGBColorSpace;
121	      }
122	    });
123	
124	    return { map, normalMap, roughnessMap };
125	  }, [gl, sourceTextures]);
126	
127	  useEffect(() => {
128	    return () => {
129	      textures.map?.dispose();
130	      textures.normalMap?.dispose();
131	      textures.roughnessMap?.dispose();
132	    };
133	  }, [textures]);
134	
135	  return useMemo(() => {
136	    return {
137	      color: '#ffffff',
138	      map: textures.map ?? undefined,
139	      normalMap: textures.normalMap ?? undefined,
140	      roughnessMap: textures.roughnessMap ?? undefined,
141	      normalScale: new THREE.Vector2(0.16, 0.16),
142	      roughness: 0.9,
143	      metalness: 0.02,
144	      envMapIntensity: 0.03,
145	    };
146	  }, [textures]);
147	}
148	
149	interface HouseFloorShellProps {
150	  elevationY: number;
151	  frontWallOpeningWidth: number;
152	  frontWallOpeningHeight: number;
153	  showFrontDoorOpening?: boolean;
154	  windowCentersX: number[];
155	  windowHoles: WallHole[];
156	  frontExteriorTextureMaps: Partial<WallMaterialProps>;
157	  frontInteriorTextureMaps: Partial<WallMaterialProps>;
158	  sideExteriorTextureMaps: Partial<WallMaterialProps>;
159	  sideInteriorTextureMaps: Partial<WallMaterialProps>;
160	  backExteriorTextureMaps: Partial<WallMaterialProps>;
161	  backInteriorTextureMaps: Partial<WallMaterialProps>;
162	}
163	
164	const HouseFloorShell: React.FC<HouseFloorShellProps> = ({
165	  elevationY,
166	  frontWallOpeningWidth,
167	  frontWallOpeningHeight,
168	  showFrontDoorOpening = true,
169	  windowCentersX,
170	  windowHoles,
171	  frontExteriorTextureMaps,
172	  frontInteriorTextureMaps,
173	  sideExteriorTextureMaps,
174	  sideInteriorTextureMaps,
175	  backExteriorTextureMaps,
176	  backInteriorTextureMaps,
177	}) => {
178	  const leftWallRef = useRef<THREE.Mesh>(null);
179	  const rightWallRef = useRef<THREE.Mesh>(null);
180	  const backWallRef = useRef<THREE.Mesh>(null);
181	
182	  useUv2(leftWallRef);
183	  useUv2(rightWallRef);
184	  useUv2(backWallRef);
185	
186	  const backWallZ = FRONT_WALL_BACK_FACE_Z - HOUSE_DEPTH;
187	  const houseFrontZ = FRONT_WALL_BACK_FACE_Z;
188	  const houseBackZ = backWallZ - WALL_THICKNESS / 2;
189	  const sideWallDepth = houseFrontZ - houseBackZ;
190	  const sideWallCenterZ = (houseFrontZ + houseBackZ) / 2;
191	  const sideWallX = WALL_WIDTH / 2 + WALL_THICKNESS / 2;
192	  const windowCenterY = FLOOR_Y + WINDOW_SILL_HEIGHT + WINDOW_HEIGHT / 2;
193	
194	  return (
195	    <group position={[0, elevationY, 0]}>
196	      <ParametricWall
197	        openingWidth={frontWallOpeningWidth}
198	        openingHeight={frontWallOpeningHeight}
199	        showDoorOpening={showFrontDoorOpening}
200	        wallColor={WALL_COLOR}
201	        position={[0, 0, WALL_CENTER_Z]}
202	        width={WALL_WIDTH + 2 * WALL_THICKNESS}
203	        additionalHoles={windowHoles}
204	        exteriorTextureMaps={frontExteriorTextureMaps}
205	        interiorTextureMaps={frontInteriorTextureMaps}
206	      />
207	
208	      {windowCentersX.map((centerX) => (
209	        <ParametricWindow
210	          key={centerX}
211	          position={[centerX, windowCenterY, WALL_CENTER_Z]}
212	        />
213	      ))}
214	
215	      <mesh
216	        ref={leftWallRef}
217	        position={[-sideWallX, 0, sideWallCenterZ]}
218	        castShadow
219	        receiveShadow
220	      >
221	        <boxGeometry args={[WALL_THICKNESS, WALL_HEIGHT, sideWallDepth]} />
222	        <meshStandardMaterial attach="material-0" {...sideInteriorTextureMaps} />
223	        <meshStandardMaterial attach="material-1" {...sideExteriorTextureMaps} />
224	        <meshStandardMaterial attach="material-2" {...sideExteriorTextureMaps} />
225	        <meshStandardMaterial attach="material-3" {...sideExteriorTextureMaps} />
226	        <meshStandardMaterial attach="material-4" {...sideExteriorTextureMaps} />
227	        <meshStandardMaterial attach="material-5" {...sideExteriorTextureMaps} />
228	      </mesh>
229	
230	      <mesh
231	        ref={rightWallRef}
232	        position={[sideWallX, 0, sideWallCenterZ]}
233	        castShadow
234	        receiveShadow
235	      >
236	        <boxGeometry args={[WALL_THICKNESS, WALL_HEIGHT, sideWallDepth]} />
237	        <meshStandardMaterial attach="material-0" {...sideExteriorTextureMaps} />
238	        <meshStandardMaterial attach="material-1" {...sideInteriorTextureMaps} />
239	        <meshStandardMaterial attach="material-2" {...sideExteriorTextureMaps} />
240	        <meshStandardMaterial attach="material-3" {...sideExteriorTextureMaps} />
241	        <meshStandardMaterial attach="material-4" {...sideExteriorTextureMaps} />
242	        <meshStandardMaterial attach="material-5" {...sideExteriorTextureMaps} />
243	      </mesh>
244	
245	      <mesh
246	        ref={backWallRef}
247	        position={[0, 0, backWallZ]}
248	        castShadow
249	        receiveShadow
250	      >
251	        <boxGeometry
252	          args={[WALL_WIDTH + 2 * WALL_THICKNESS, WALL_HEIGHT, WALL_THICKNESS]}
253	        />
254	        <meshStandardMaterial attach="material-0" {...backExteriorTextureMaps} />
255	        <meshStandardMaterial attach="material-1" {...backExteriorTextureMaps} />
256	        <meshStandardMaterial attach="material-2" {...backExteriorTextureMaps} />
257	        <meshStandardMaterial attach="material-3" {...backExteriorTextureMaps} />
258	        <meshStandardMaterial attach="material-4" {...backInteriorTextureMaps} />
259	        <meshStandardMaterial attach="material-5" {...backExteriorTextureMaps} />
260	      </mesh>
261	    </group>
262	  );
263	};
264	
265	interface ConcreteBoxProps {
266	  materialProps: Partial<WallMaterialProps>;
267	  position: [number, number, number];
268	  size: [number, number, number];
269	}
270	
271	const ConcreteBox: React.FC<ConcreteBoxProps> = ({
272	  materialProps,
273	  position,
274	  size,
275	}) => {
276	  const ref = useRef<THREE.Mesh>(null);
277	
278	  useUv2(ref);
279	
280	  return (
281	    <mesh ref={ref} position={position} castShadow receiveShadow>
282	      <boxGeometry args={size} />
283	      <meshStandardMaterial {...materialProps} />
284	    </mesh>
285	  );
286	};
287	
288	interface ParametricHouseProps {
289	  proposal?: Proposal;
290	}
291	
292	export const ParametricHouse: React.FC<ParametricHouseProps> = ({ proposal }) => {
293	  // Read door dimensions to compute front wall opening
294	  const selectedDoorWidthMm = useDoorWidth();
295	  const selectedDoorHeightMm = useDoorHeight();
296	  const selectedTopGlassHeightMm = useDoorUpperGlassHeight();
297	  const selectedLeftGlassWidthMm = useDoorLeftGlassWidth();
298	  const selectedRightGlassWidthMm = useDoorRightGlassWidth();
299	  const selectedLayout = useDoorLayout();
300	  const selectedExteriorFinish = useSceneExteriorWallFinish();
301	  const selectedExteriorColor = useSceneExteriorWallColor();
302	  const selectedInteriorColor = useSceneInteriorWallColor();
303	  const doorWidth = mmToM(
304	    clampDoorWidthMm(proposal?.doorWidth ?? selectedDoorWidthMm),
305	  );
306	  const doorHeight = mmToM(
307	    clampDoorHeightMm(proposal?.doorHeight ?? selectedDoorHeightMm),
308	  );
309	
310	  const topGlassHeight = mmToM(
311	    proposal?.topGlassHeight ?? selectedTopGlassHeightMm,
312	  );
313	  const leftGlassWidth = mmToM(
314	    proposal?.leftGlassWidth ?? selectedLeftGlassWidthMm,
315	  );
316	  const rightGlassWidth = mmToM(
317	    proposal?.rightGlassWidth ?? selectedRightGlassWidthMm,
318	  );
319	
320	  const layout = proposal?.layout ?? selectedLayout;
321	  const exteriorFinish = proposal?.sceneExteriorWallFinish ?? selectedExteriorFinish;
322	  const exteriorColor = proposal?.sceneExteriorWallColor ?? selectedExteriorColor;
323	  const interiorFinish = sceneWallFinishes[0];
324	  const interiorColor = proposal?.sceneInteriorWallColor ?? selectedInteriorColor;
325	  const hasTopGlass = layout?.id?.includes('top') ?? false;
326	  const hasLeftGlass = layout?.id?.includes('left') ?? false;
327	  const hasRightGlass = layout?.id?.includes('right') ?? false;
328	
329	  const actualTopGlassHeight = hasTopGlass ? topGlassHeight : 0;
330	  const actualLeftGlassWidth = hasLeftGlass ? leftGlassWidth : 0;
331	  const actualRightGlassWidth = hasRightGlass ? rightGlassWidth : 0;
332	
333	  // Door opening dimensions (same logic as ParametricDoor)
334	  const doorOpeningWidth =
335	    doorWidth +
336	    actualLeftGlassWidth +
337	    actualRightGlassWidth +
338	    FRAME_PROFILE_WIDTH * 2;
339	
340	  let topOffset = FRAME_PROFILE_WIDTH;
341	  if (hasTopGlass) topOffset += actualTopGlassHeight;
342	  const doorOpeningHeight = doorHeight + FRAME_PROFILE_WIDTH_BOTTOM + topOffset;
343	
344	  // Front wall uses ExtrudeGeometry while side/back walls use BoxGeometry,
345	  // so each surface family needs its own texture repeat scale.
346	  const frontExteriorTextures = useWallSurfaceMaterial(
347	    0.5,
348	    0.5,
349	    exteriorFinish,
350	    exteriorColor,
351	  );
352	  const frontInteriorTextures = useWallSurfaceMaterial(
353	    0.5,
354	    0.5,
355	    interiorFinish,
356	    interiorColor,
357	  );
358	  const sideExteriorTextures = useWallSurfaceMaterial(
359	    HOUSE_DEPTH / 2,
360	    WALL_HEIGHT / 2,
361	    exteriorFinish,
362	    exteriorColor,
363	  );
364	  const sideInteriorTextures = useWallSurfaceMaterial(
365	    HOUSE_DEPTH / 2,
366	    WALL_HEIGHT / 2,
367	    interiorFinish,
368	    interiorColor,
369	  );
370	  const backExteriorTextures = useWallSurfaceMaterial(
371	    (WALL_WIDTH + 2 * WALL_THICKNESS) / 2,
372	    WALL_HEIGHT / 2,
373	    exteriorFinish,
374	    exteriorColor,
375	  );
376	  const backInteriorTextures = useWallSurfaceMaterial(
377	    (WALL_WIDTH + 2 * WALL_THICKNESS) / 2,
378	    WALL_HEIGHT / 2,
379	    interiorFinish,
380	    interiorColor,
381	  );
382	
383	  const lowerWindowCenters = useMemo(() => [WINDOW_CENTER_X], []);
384	  const upperWindowCenters = useMemo(
385	    () => [WINDOW_CENTER_X, UPPER_WINDOW_CENTER_X],
386	    [],
387	  );
388	  const lowerWindowHoles = useMemo(
389	    () =>
390	      lowerWindowCenters.map((centerX) => ({
391	        centerX,
392	        bottomY: FLOOR_Y + WINDOW_SILL_HEIGHT,
393	        width: WINDOW_WIDTH,
394	        height: WINDOW_HEIGHT,
395	      })),
396	    [lowerWindowCenters],
397	  );
398	  const upperWindowHoles = useMemo(
399	    () =>
400	      upperWindowCenters.map((centerX) => ({
401	        centerX,
402	        bottomY: FLOOR_Y + WINDOW_SILL_HEIGHT,
403	        width: WINDOW_WIDTH,
404	        height: WINDOW_HEIGHT,
405	      })),
406	    [upperWindowCenters],
407	  );
408	  const upperFloorOffsetY = WALL_HEIGHT + INTER_FLOOR_SLAB_THICKNESS;
409	  const foundationTopY = FLOOR_Y - FOUNDATION_TOP_CLEARANCE;
410	  const foundationCenterY = foundationTopY - FOUNDATION_HEIGHT / 2;
411	  const foundationWidth = WALL_WIDTH + 2 * WALL_THICKNESS;
412	  const foundationDepth = HOUSE_DEPTH + WALL_THICKNESS;
413	  const foundationCenterZ = WALL_CENTER_Z - HOUSE_DEPTH / 2;
414	  const foundationFrontFaceZ = foundationCenterZ + foundationDepth / 2;
415	  const interFloorSlabWidth = foundationWidth - INTER_FLOOR_SLAB_INSET * 2;
416	  const interFloorSlabDepth = foundationDepth - INTER_FLOOR_SLAB_INSET * 2;
417	  const interFloorSlabCenterY =
418	    CEILING_Y + INTER_FLOOR_SLAB_THICKNESS / 2;
419	  const interFloorSlabCenterZ = foundationCenterZ;
420	  const stepHeight = FOUNDATION_HEIGHT / STEP_COUNT;
421	  const stepBaseY = foundationTopY - FOUNDATION_HEIGHT;
422	  const lowerStepDepth = STEP_DEPTH * STEP_COUNT;
423	  const interiorFloorYs = [
424	    foundationTopY + INTERIOR_FLOOR_SURFACE_OFFSET,
425	    interFloorSlabCenterY +
426	      INTER_FLOOR_SLAB_THICKNESS / 2 +
427	      INTERIOR_FLOOR_SURFACE_OFFSET,
428	  ];
429	  const foundationMaterialProps = useFacadeTextures(
430	    foundationWidth / 2,
431	    FOUNDATION_HEIGHT / 2,
432	    FOUNDATION_COLOR,
433	  );
434	  const accentConcreteMaterialProps = useFacadeTextures(
435	    interFloorSlabWidth / 2,
436	    INTER_FLOOR_SLAB_THICKNESS / 2,
437	    DARK_CONCRETE_COLOR,
438	  );
439	  const interiorFloorMaterialProps = useInteriorFloorMaterial();
440	  const baseStairMaterialProps = useFacadeTextures(
441	    UPPER_STEP_WIDTH / 2,
442	    FOUNDATION_HEIGHT / 2,
443	    STAIR_CONCRETE_COLOR,
444	  );
445	  const stairMaterialProps = useMemo(
446	    () => ({
447	      ...baseStairMaterialProps,
448	      roughness: 1,
449	      roughnessMap: undefined,
450	      metalness: 0,
451	      envMapIntensity: 0,
452	      aoMapIntensity: 0.12,
453	      normalScale: new THREE.Vector2(0.05, 0.05),
454	    }),
455	    [baseStairMaterialProps],
456	  );
457	  const stairConfigs = useMemo(
458	    () => [
459	      {
460	        key: 'lower-step',
461	        width: LOWER_STEP_WIDTH,
462	        height: stepHeight,
463	        depth: lowerStepDepth,
464	      },
465	      {
466	        key: 'upper-step',
467	        width: UPPER_STEP_WIDTH,
468	        height: FOUNDATION_HEIGHT,
469	        depth: UPPER_STEP_DEPTH,
470	      },
471	    ],
472	    [lowerStepDepth, stepHeight],
473	  );
474	
475	  // Roof dimensions (flush with walls)
476	  const roofWidth = WALL_WIDTH + 2 * WALL_THICKNESS;
477	  const roofDepth = HOUSE_DEPTH + WALL_THICKNESS;
478	  const roofY = CEILING_Y + upperFloorOffsetY + ROOF_THICKNESS / 2;
479	  const roofZ = WALL_CENTER_Z - HOUSE_DEPTH / 2;
480	
481	  // Fascia: thin dark strip along front edge of roof
482	  const roofBottomY = roofY - ROOF_THICKNESS / 2;
483	  const roofFrontFaceZ = roofZ + roofDepth / 2;
484	  const fasciaY = roofBottomY + FASCIA_HEIGHT / 2;
485	  const fasciaZ = roofFrontFaceZ - FASCIA_DEPTH / 2;
486	
487	  // Floor
488	  const floorWidth = WALL_WIDTH;
489	  const floorDepth = HOUSE_DEPTH;
490	  const floorZ = FRONT_WALL_BACK_FACE_Z - HOUSE_DEPTH / 2;
491	
492	  return (
493	    <group>
494	      <HouseFloorShell
495	        elevationY={0}
496	        frontWallOpeningWidth={doorOpeningWidth}
497	        frontWallOpeningHeight={doorOpeningHeight}
498	        windowCentersX={lowerWindowCenters}
499	        windowHoles={lowerWindowHoles}
500	        frontExteriorTextureMaps={frontExteriorTextures}
501	        frontInteriorTextureMaps={frontInteriorTextures}
502	        sideExteriorTextureMaps={sideExteriorTextures}
503	        sideInteriorTextureMaps={sideInteriorTextures}
504	        backExteriorTextureMaps={backExteriorTextures}
505	        backInteriorTextureMaps={backInteriorTextures}
506	      />
507	
508	      <HouseFloorShell
509	        elevationY={upperFloorOffsetY}
510	        frontWallOpeningWidth={doorOpeningWidth}
511	        frontWallOpeningHeight={doorOpeningHeight}
512	        showFrontDoorOpening={false}
513	        windowCentersX={upperWindowCenters}
514	        windowHoles={upperWindowHoles}
515	        frontExteriorTextureMaps={frontExteriorTextures}
516	        frontInteriorTextureMaps={frontInteriorTextures}
517	        sideExteriorTextureMaps={sideExteriorTextures}
518	        sideInteriorTextureMaps={sideInteriorTextures}
519	        backExteriorTextureMaps={backExteriorTextures}
520	        backInteriorTextureMaps={backInteriorTextures}
521	      />
522	
523	      <ConcreteBox
524	        materialProps={foundationMaterialProps}
525	        position={[0, foundationCenterY, foundationCenterZ]}
526	        size={[foundationWidth, FOUNDATION_HEIGHT, foundationDepth]}
527	      />
528	
529	      <ConcreteBox
530	        materialProps={accentConcreteMaterialProps}
531	        position={[0, interFloorSlabCenterY, interFloorSlabCenterZ]}
532	        size={[
533	          interFloorSlabWidth,
534	          INTER_FLOOR_SLAB_THICKNESS,
535	          interFloorSlabDepth,
536	        ]}
537	      />
538	
539	      {stairConfigs.map((stepConfig) => {
540	        const { key, width, height, depth } = stepConfig;
541	        const centerY = stepBaseY + height / 2;
542	        const centerZ = foundationFrontFaceZ + depth / 2;
543	
544	        return (
545	          <ConcreteBox
546	            key={key}
547	            materialProps={stairMaterialProps}
548	            position={[0, centerY, centerZ]}
549	            size={[width, height, depth]}
550	          />
551	        );
552	      })}
553	
554	      {/* Flat roof with overhang */}
555	      <mesh position={[0, roofY, roofZ]} castShadow receiveShadow>
556	        <boxGeometry args={[roofWidth, ROOF_THICKNESS, roofDepth]} />
557	        <meshStandardMaterial color={ROOF_COLOR} />
558	      </mesh>
559	
560	      {/* Roof edge fascia — thin dark strip along front edge */}
561	      <mesh position={[0, fasciaY, fasciaZ]}>
562	        <boxGeometry args={[roofWidth, FASCIA_HEIGHT, FASCIA_DEPTH]} />
563	        <meshStandardMaterial color={FASCIA_COLOR} />
564	      </mesh>
565	
566	      {interiorFloorYs.map((y) => (
567	        <mesh
